:root {

  /* ---- Brand / Primitive: Greys ---- */
  --zimm-color-grey-black: black;
  --zimm-color-grey-900:   #191919;
  --zimm-color-grey-800:   #282828;
  --zimm-color-grey-700:   #454545;
  --zimm-color-grey-600:   #666;
  --zimm-color-grey-500:   #707070;
  --zimm-color-grey-300:   #969696;
  --zimm-color-grey-200:   #d1d1d1;
  --zimm-color-grey-100:   #e6e6e6;
  --zimm-color-grey-white: white;

  /* ---- Brand / Primitive: Ivory ---- */
  --zimm-color-ivory-400: #f2e9e0;
  --zimm-color-ivory-300: #fbf5ef;
  --zimm-color-ivory-200: #f6f4f1;
  --zimm-color-ivory-100: #f9f8f6;

  /* ---- Brand / Primitive: Status ---- */
  --zimm-color-coral-500:  #f98f8c;
  --zimm-color-green-500:  #2d5a3d;
  --zimm-color-orange-500: #d67600;
  --zimm-color-red-500:    #9c0000;

  /* ---- Brand / Primitive: Opacity (base: grey/900 #191919) ---- */
  --zimm-color-opacity-50: rgba(25, 25, 25, 0.50);
  --zimm-color-opacity-40: rgba(25, 25, 25, 0.40);
  --zimm-color-opacity-30: rgba(25, 25, 25, 0.30);
  --zimm-color-opacity-15: rgba(25, 25, 25, 0.15);

  /* ---- Alias / Semantic: Text ---- */
  --zimm-color-text-default:      var(--zimm-color-grey-900);
  --zimm-color-text-inverse:      var(--zimm-color-grey-white);
  --zimm-color-text-inverse-grey: #969696; /* confirmed: alias/color/text/inverse/subtle → brand/color/palette/natural/300 */
  --zimm-color-text-secondary:    var(--zimm-color-grey-600);
  --zimm-color-text-muted:        var(--zimm-color-grey-300);

  /* ---- Alias / Semantic: Background ---- */
  --zimm-color-bg-01: var(--zimm-color-ivory-100);
  --zimm-color-bg-02: var(--zimm-color-ivory-200);
  --zimm-color-bg-03: var(--zimm-color-ivory-300);
  --zimm-color-bg-04: var(--zimm-color-ivory-400);
  --zimm-color-bg-05: var(--zimm-color-grey-900);
  --zimm-color-bg-06: var(--zimm-color-grey-800);
  --zimm-color-bg-07: var(--zimm-color-grey-white);

  /* ---- Alias / Semantic: Border ---- */
  --zimm-color-border-default:   var(--zimm-color-grey-100);
  --zimm-color-border-secondary: var(--zimm-color-grey-200);
  --zimm-color-border-focus:     var(--zimm-color-grey-900);
  --zimm-color-border-forms:     var(--zimm-color-grey-500);

  /* ---- Alias / Semantic: Status ---- */
  --zimm-color-status-success:      var(--zimm-color-green-500);
  --zimm-color-status-error:        var(--zimm-color-red-500);
  --zimm-color-status-error-bg:     var(--zimm-color-coral-500);
  --zimm-color-status-store-closed: var(--zimm-color-orange-500);

  /* ---- Alias / Semantic: Link ---- */
  --zimm-color-link-default: var(--zimm-color-grey-900);
  --zimm-color-link-hover:   var(--zimm-color-grey-500);

  /* ---- Alias / Semantic: Icon ---- */
  --zimm-color-icon-default: var(--zimm-color-grey-900);

  /* ---- Alias / Semantic: Action: Primary ---- */
  --zimm-color-action-primary-bg-default:  var(--zimm-color-grey-900);
  --zimm-color-action-primary-bg-hover:    var(--zimm-color-grey-300);
  --zimm-color-action-primary-bg-pressed:  var(--zimm-color-grey-700);
  --zimm-color-action-primary-bg-disabled: var(--zimm-color-grey-200);
  --zimm-color-action-primary-bg-focused:  var(--zimm-color-grey-black);
  --zimm-color-action-primary-text:         var(--zimm-color-grey-white);
  --zimm-color-action-primary-text-disabled: var(--zimm-color-grey-300);

  /* ---- Alias / Semantic: Action: Secondary ---- */
  --zimm-color-action-secondary-border:          var(--zimm-color-grey-900);
  --zimm-color-action-secondary-bg-hover:        var(--zimm-color-ivory-100);
  --zimm-color-action-secondary-text:            var(--zimm-color-grey-900);
  --zimm-color-action-secondary-text-inverse:    var(--zimm-color-grey-white);
  --zimm-color-action-secondary-text-disabled:   var(--zimm-color-grey-300);

  /* ---- Typography: Font families ---- */
  --zimm-font-family-heading: 'Futura Round', sans-serif;
  --zimm-font-family-body:    'Futura Round', sans-serif;
  --zimm-font-family-serif:   'Source Serif 4', serif;

  /* ---- Typography: Font sizes ---- */
  --zimm-font-size-md:  24px;
  --zimm-font-size-xs:  16px;
  --zimm-font-size-2xs: 14px;
  --zimm-font-size-3xs: 12px;
  --zimm-font-size-4xs: 10px;

  /* ---- Typography: Line heights ---- */
  --zimm-font-lineheight-md:  32px;
  --zimm-font-lineheight-xs:  24px;
  --zimm-font-lineheight-2xs: 18px;
  --zimm-font-lineheight-3xs: 16px;
  --zimm-font-lineheight-4xs: 14px;

  /* ---- Typography: Letter spacing ---- */
  --zimm-font-letterspacing-sm: 0px;
  --zimm-font-letterspacing-xs:     -0.12px;
  --zimm-font-letterspacing-footer:  0.4px;

  /* ---- Typography: Font weights ---- */
  --zimm-font-weight-medium:  500;
  --zimm-font-weight-regular: 400;

  /* ---- Spacing scale ---- */
  --zimm-scale-3xs:  2px;
  --zimm-scale-2xs:  4px;
  --zimm-scale-xs:   8px;
  --zimm-scale-s:    12px;
  --zimm-scale-m:    16px;
  --zimm-scale-l:    20px;
  --zimm-scale-xl:   24px;
  --zimm-scale-2xl:  32px;
  --zimm-scale-3xl:  40px;
  --zimm-scale-4xl:  64px;
  --zimm-scale-5xl:  80px;
  --zimm-scale-6xl:  128px;
  --zimm-scale-7xl:  160px;

  /* ---- Spacing: numeric aliases (Figma scale token names -> named tokens) ---- */
  --zimm-scale-025:  1px;
  --zimm-scale-200:  var(--zimm-scale-xs);
  --zimm-scale-300:  var(--zimm-scale-s);
  --zimm-scale-400:  var(--zimm-scale-m);
  --zimm-scale-500:  var(--zimm-scale-l);
  --zimm-scale-600:  var(--zimm-scale-xl);
  --zimm-scale-700:  28px;
  --zimm-scale-800:  var(--zimm-scale-2xl);
  --zimm-scale-1000: var(--zimm-scale-3xl);
  --zimm-scale-1100: 44px;
  --zimm-scale-1200: 48px;
  --zimm-scale-1300: 52px;
  --zimm-scale-1600: var(--zimm-scale-4xl);
  --zimm-scale-3500: 140px;
  --zimm-scale-4500: 180px;

  /* ---- Spacing: Grid margins ----
     NOTE (dev): These tokens define the outer horizontal padding for the layout grid at each breakpoint.
     Use --zimm-grid-margin-mobile / -tablet / -desktop anywhere a component needs to align with the grid
     edge (e.g. full-bleed cards, sticky panels). Do not hardcode 30px / 24px / 0 in component styles.
     Source: Figma grid definitions. No matching spacing-scale token exists for 30px or 24px.
     --------------------------------------------------------- */
  --zimm-grid-margin-mobile:  30px;
  --zimm-grid-margin-tablet:  24px;
  --zimm-grid-margin-desktop: 0px;

  /* ---- Spacing: Action sizing (alias) ---- */
  --zimm-size-action-height-lg:    52px;
  --zimm-size-action-height-md:    40px;
  --zimm-size-action-padding-h-lg: 32px;
  --zimm-size-action-padding-h-md: 20px;
  --zimm-size-action-gap:          16px; /* Figma: --alias/space/action/gap/400 */

  /* ---- Motion: PLACEHOLDER ----
     All transition and animation values below are provisional.
     Motion design is in progress and subject to change pending
     formal approval. Do not treat these values as final.
     --------------------------------------------------------- */

  /* ---- Motion: Durations ---- */
  --zimm-motion-duration-fast:    200ms;
  --zimm-motion-duration-default: 300ms;
  --zimm-motion-duration-slow:    500ms;

  /* ---- Motion: Easings ---- */
  --zimm-motion-easing-standard: ease;
  --zimm-motion-easing-slides:   cubic-bezier(0.87, 0, 0.13, 1);
  --zimm-motion-easing-fades:    cubic-bezier(0.37, 0, 0.63, 1);

  /* ---- Border widths ---- */
  --zimm-border-width-default: 1px;

  /* ---- Icon sizes ---- */
  --zimm-icon-size-lg: 20px;
  --zimm-icon-size-md: 16px;
  --zimm-icon-size-sm: 12px;

}


