/* Button component classes: .zimm-btn*
   Source: MCP-Test--Don-t-Use (Zimmermann Design System 2026)
   Component: zimm-button (02-design/library/elements/button/)
   Moved here from the component's own zimm-button.css: 2026-07-25.
   Promoted to a shared token-level file (imported by common.css, same as
   colors/typography/spacing) because zimm-btn* classes are reused directly
   by other components' native <button> markup (e.g. filters/sort controls),
   not only by zimm-button's own render function -- every page already links
   common.css, so this makes button styling available everywhere without a
   separate <link> per composing demo. The render function itself
   (zimm-button.js) still lives in its own element folder; only the CSS moved.
   Managed by /extract, do not edit manually.
   --------------------------------------------------------- */

/* ---- Label variants (primary/secondary): shared structural rules ---- */

.zimm-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--zimm-size-action-gap);
  min-width: 80px;
  overflow: clip;
  cursor: pointer;
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  text-transform: uppercase;
  letter-spacing: var(--zimm-font-letterspacing-sm);
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.zimm-btn-full {
  display: flex;
  width: 100%;
}

/* Size: Large | Medium in Figma. Both get an explicit, parallel rule here —
   neither is an implicit default baked into the base .zimm-btn rule, even
   though large happens to be the contract default. The renderer always emits
   a zimm-btn-[size] class (never omits it for the default), so the CSS
   should always have a matching rule for it to point to. */

.zimm-btn-large {
  height: var(--zimm-size-action-height-lg);
  padding: 0 var(--zimm-size-action-padding-h-lg);
  font-size: var(--zimm-font-size-2xs);
  line-height: var(--zimm-font-lineheight-3xs);
}

.zimm-btn-medium {
  height: var(--zimm-size-action-height-md);
  padding: 0 var(--zimm-size-action-padding-h-md);
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-2xs);
}

/* ---- Resting colours ---- */

.zimm-btn-primary {
  background: var(--zimm-color-action-primary-bg-default);
  color: var(--zimm-color-action-primary-text);
  border: none;
}

.zimm-btn-primary.zimm-btn-inverse {
  background: var(--zimm-color-grey-white);
  color: var(--zimm-color-grey-900);
}

.zimm-btn-secondary {
  background: transparent;
  color: var(--zimm-color-action-secondary-text);
  border: var(--zimm-border-width-default) solid var(--zimm-color-action-secondary-border);
}

.zimm-btn-secondary.zimm-btn-inverse {
  color: var(--zimm-color-grey-white);
  border-color: var(--zimm-color-grey-white);
}

/* ---- Hover ---- */

.zimm-btn-primary:hover:not(:disabled) {
  background: var(--zimm-color-action-primary-bg-hover);
  color: var(--zimm-color-action-primary-text);
}

.zimm-btn-primary.zimm-btn-inverse:hover:not(:disabled) {
  background: var(--zimm-color-ivory-100);
  color: var(--zimm-color-grey-900);
}

.zimm-btn-secondary:hover:not(:disabled) {
  background: var(--zimm-color-action-secondary-bg-hover);
  color: var(--zimm-color-action-secondary-text);
}

.zimm-btn-secondary.zimm-btn-inverse:hover:not(:disabled) {
  background: var(--zimm-color-action-secondary-bg-hover);
  border-color: var(--zimm-color-grey-white);
}

/* ---- Active / pressed ----
   Confirmed against Figma (node 901:2897): pressed fills solid the same way
   for every variant/inverse combination — bg and border both become
   --alias/color/action/primary/bg/pressed (#454545 / --zimm-color-grey-700),
   text becomes white in every case. This resolves what was previously an
   unflagged gap in the original implementation (it never branched on inverse
   at all) and the TODOs from the first CSS pass. ---- */

.zimm-btn-primary:active:not(:disabled) {
  background: var(--zimm-color-action-primary-bg-pressed);
  color: var(--zimm-color-action-secondary-text-inverse);
}

.zimm-btn-primary.zimm-btn-inverse:active:not(:disabled) {
  background: var(--zimm-color-action-primary-bg-pressed);
  color: var(--zimm-color-grey-white);
}

.zimm-btn-secondary:active:not(:disabled) {
  background: var(--zimm-color-action-primary-bg-pressed);
  color: var(--zimm-color-action-secondary-text-inverse);
  border-color: var(--zimm-color-action-primary-bg-pressed);
}

.zimm-btn-secondary.zimm-btn-inverse:active:not(:disabled) {
  background: var(--zimm-color-action-primary-bg-pressed);
  color: var(--zimm-color-grey-white);
  border-color: var(--zimm-color-grey-700);
}

/* ---- Focus-visible ---- */

.zimm-btn-primary:focus-visible {
  outline: var(--zimm-focus-ring);
  outline-offset: 2px;
}

.zimm-btn-primary.zimm-btn-inverse:focus-visible {
  outline-color: var(--zimm-color-grey-white);
}

.zimm-btn-secondary:focus-visible {
  outline: var(--zimm-focus-ring);
  outline-offset: 3px;
}

.zimm-btn-secondary.zimm-btn-inverse:focus-visible {
  outline-color: var(--zimm-color-grey-white);
}

/* ---- Disabled ----
   Confirmed against Figma: disabled uses identical values whether inverse or
   not — the disabled treatment overrides the inverse context entirely. */

.zimm-btn-primary:disabled {
  cursor: not-allowed;
  background: var(--zimm-color-action-primary-bg-disabled);
  color: var(--zimm-color-action-primary-text-disabled);
  border-color: transparent;
}

.zimm-btn-primary.zimm-btn-inverse:disabled {
  /* Confirmed against Figma: disabled uses the same light-grey treatment
     regardless of inverse context — the disabled state overrides it. */
  background: var(--zimm-color-action-primary-bg-disabled);
  color: var(--zimm-color-action-primary-text-disabled);
}

.zimm-btn-secondary:disabled {
  cursor: not-allowed;
  background: transparent;
  color: var(--zimm-color-action-secondary-text-disabled);
  border-color: var(--zimm-color-action-secondary-text-disabled);
}

.zimm-btn-secondary.zimm-btn-inverse:disabled {
  /* Confirmed against Figma: same values as non-inverse disabled. */
  color: var(--zimm-color-action-secondary-text-disabled);
  border-color: var(--zimm-color-action-secondary-text-disabled);
}

/* ---- Icon variant: distinct structural shape ---- */

.zimm-btn-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  padding: 8px;
  cursor: pointer;
  transition: opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
}

.zimm-btn-icon:hover:not(:disabled) {
  opacity: 0.6;
}

.zimm-btn-icon:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

.zimm-btn-icon:focus-visible {
  outline: var(--zimm-focus-ring);
  outline-offset: 2px;
  border-radius: 2px;
}

.zimm-btn-icon.zimm-btn-inverse:focus-visible {
  outline-color: var(--zimm-color-grey-white);
}

.zimm-btn-icon img {
  display: block;
  width: 20px;
  height: 20px;
}

.zimm-btn-icon.zimm-btn-inverse img {
  filter: invert(1);
}

